public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static String s;
    static long target;
    static int pos;
    static final long INF = Long.MAX_VALUE / 4;

    static class Result {
        long len;
        char found;
        boolean hasFound;

        Result(long len, char found, boolean hasFound) {
            this.len = len;
            this.found = found;
            this.hasFound = hasFound;
        }
    }

    static long capMul(long a, long b) {
        if (a == 0 || b == 0) return 0;
        if (a > INF / b) return INF;
        return a * b;
    }

    static long capAdd(long a, long b) {
        if (a > INF - b) return INF;
        return a + b;
    }

    static Result parseExpr() {
        long totalLen = 0;
        while (pos < s.length() && s.charAt(pos) != ')') {
            Result part = parseTerm();
            if (part.hasFound) return part;
            totalLen = capAdd(totalLen, part.len);
        }
        return new Result(totalLen, '\0', false);
    }

    static Result parseTerm() {
        long repeat = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            repeat = repeat * 10 + (s.charAt(pos) - '0');
            pos++;
        }
        if (repeat == 0) repeat = 1;

        long unitLen;
        char found = '\0';
        boolean hasFound = false;

        if (s.charAt(pos) == '(') {
            pos++; // skip '('
            int startPos = pos;
            Result inner = parseExpr();
            if (inner.hasFound) return inner;
            unitLen = inner.len;
            pos++; // skip ')'

            long totalBlockLen = capMul(unitLen, repeat);
            if (target < totalBlockLen) {
                long offset = target % unitLen;
                long oldTarget = target;
                target = offset;
                pos = startPos;
                Result retry = parseExpr();
                if (retry.hasFound) return retry;
                target = oldTarget; // not really needed
            }
            return new Result(totalBlockLen, '\0', false);
        } else {
            char c = s.charAt(pos++);
            unitLen = 1;
            long totalBlockLen = repeat;
            if (target < totalBlockLen) {
                return new Result(0, c, true);
            }
            return new Result(totalBlockLen, '\0', false);
        }
    }

