// Represents a node in the parse tree
struct Node {
    char ch;          // character if leaf
    int repeat;       // repetition count
    vector<Node*> children; // child sequences
    long long len;    // total length of uncompressed string from this node
    Node(char c) : ch(c), repeat(1), len(1) {}
    Node(int r) : ch(0), repeat(r), len(0) {}
};

// Build parse tree recursively
Node* parse(const string& s, int& pos) {
    Node* node = new Node(1); // dummy repeat 1 for sequence
    while (pos < (int)s.size() && s[pos] != ')') {
        if (isupper(s[pos])) {
            // single letter
            node->children.push_back(new Node(s[pos]));
            pos++;
        } else if (isdigit(s[pos])) {
            // compressed block: number(
            int num = 0;
            while (pos < (int)s.size() && isdigit(s[pos])) {
                num = num * 10 + (s[pos] - '0');
                pos++;
            }
            // expect '('
            pos++; // skip '('
            Node* child = parse(s, pos);
            child->repeat = num;
            // expect ')'
            pos++; // skip ')'
            node->children.push_back(child);
        }
    }
    // compute total length
    node->len = 0;
    for (auto* c : node->children) {
        node->len += c->len * c->repeat;
    }
    return node;
}

// Find character at position i (0-indexed) in the uncompressed string of node
char findChar(Node* node, long long i) {
    for (auto* child : node->children) {
        long long blockLen = child->len * child->repeat;
        if (i < blockLen) {
            long long innerIndex = i % child->len;
            if (child->children.empty()) {
                // leaf
                return child->ch;
            } else {
                return findChar(child, innerIndex);
            }
        }
        i -= blockLen;
    }
    return '?'; // should never reach
}

