static const i128 INF = (i128)4e18; // safely above any reasonable query range

i128 capMul(i128 a, i128 b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF / b) return INF;
    return a * b;
}

i128 capAdd(i128 a, i128 b) {
    if (a >= INF || b >= INF) return INF;
    if (a > INF - b) return INF;
    return a + b;
}

