}

int parseExpr() {
    vector<int> parts;
    while (posi < (int)s.size() && s[posi] != ')') {
        parts.push_back(parseTerm());
    }
    if (parts.size() == 1) return parts[0];

    Node nd;
    nd.type = 0;
    nd.lit = ""; // unused for concat node, handled by storing as special chain below
    nd.len = 0;

    // Build concatenation as binary-like flattened through extra nodes of type 2 conceptually.
    // To keep it simple, encode concatenation using repetition node impossible,
    // instead create literal-empty nodes is not enough, so store a custom concat chain.
    // We'll emulate concat by creating type 2 nodes.
    return -1;
}

struct CNode {
    int type; // 0 literal, 1 repeat, 2 concat
    string lit;
    int child = -1;
    long long rep = 1;
    vector<int> parts;
    i128 len = 0;
};

vector<CNode> tree;
int p = 0;

int parseE() {
    vector<int> parts;
    while (p < (int)s.size() && s[p] != ')') {
        if (isupper(s[p])) {
            string t;
            while (p < (int)s.size() && isupper(s[p])) t += s[p++];
            CNode nd;
            nd.type = 0;
            nd.lit = t;
            nd.len = (i128)t.size();
            tree.push_back(nd);
            parts.push_back((int)tree.size() - 1);
        } else {
            long long num = 0;
            while (p < (int)s.size() && isdigit(s[p])) num = num * 10 + (s[p++] - '0');
            p++; // '('
            int in = parseE();
            p++; // ')'
            CNode nd;
            nd.type = 1;
            nd.child = in;
            nd.rep = num;
            nd.len = capMul(tree[in].len, (i128)num);
            tree.push_back(nd);
            parts.push_back((int)tree.size() - 1);
        }
    }
    if (parts.size() == 1) return parts[0];
    CNode nd;
    nd.type = 2;
    nd.parts = parts;
    nd.len = 0;
    for (int id : parts) nd.len = capAdd(nd.len, tree[id].len);
    tree.push_back(nd);
    return (int)tree.size() - 1;
}

char kth(int id, i128 k) { // 1-based
    CNode &nd = tree[id];
    if (nd.type == 0) {
        return nd.lit[(long long)(k - 1)];
    } else if (nd.type == 1) {
        i128 childLen = tree[nd.child].len;
        i128 kk = (k - 1) % childLen + 1;
        return kth(nd.child, kk);
    } else {
        for (int ch : nd.parts) {
            if (k > tree[ch].len) k -= tree[ch].len;
            else return kth(ch, k);
        }
    }
    return '?';
}

