typedef unsigned long long ull;

#define INF ((ull)4e18)

typedef struct {
    int type;          // 0 = literal, 1 = repeat
    char ch;           // for literal
    int child;         // for repeat
    ull mul;           // for repeat
    ull len;           // expanded length
} Node;

static Node *nodes = NULL;
static int nodes_sz = 0, nodes_cap = 0;

static const char *s;
static int posi, n;

static void ensure_nodes() {
    if (nodes_sz >= nodes_cap) {
        nodes_cap = nodes_cap ? nodes_cap * 2 : 1024;
        nodes = (Node *)realloc(nodes, nodes_cap * sizeof(Node));
    }
}

static ull clamp_mul(ull a, ull b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF / b) return INF;
    return a * b;
}

static int new_literal(char c) {
    ensure_nodes();
    nodes[nodes_sz].type = 0;
    nodes[nodes_sz].ch = c;
    nodes[nodes_sz].child = -1;
    nodes[nodes_sz].mul = 1;
    nodes[nodes_sz].len = 1;
    return nodes_sz++;
}

static int new_repeat(int child, ull mul) {
    ensure_nodes();
    nodes[nodes_sz].type = 1;
    nodes[nodes_sz].ch = 0;
    nodes[nodes_sz].child = child;
    nodes[nodes_sz].mul = mul;
    nodes[nodes_sz].len = clamp_mul(nodes[child].len, mul);
    return nodes_sz++;
}

static ull read_number() {
    ull x = 0;
    while (posi < n && isdigit((unsigned char)s[posi])) {
        int d = s[posi] - '0';
        if (x > INF / 10) x = INF;
        else {
            x = x * 10 + d;
            if (x > INF) x = INF;
        }
        posi++;
    }
    return x;
}

/*
Grammar handled:
expr := term*
term := LETTER | NUMBER '(' expr ')'
*/
static int parse_expr() {
    int first = -1;
    while (posi < n && s[posi] != ')') {
        int cur;
        if (isupper((unsigned char)s[posi])) {
            cur = new_literal(s[posi]);
            posi++;
        } else if (isdigit((unsigned char)s[posi])) {
            ull k = read_number();
            if (posi < n && s[posi] == '(') posi++;
            int inside = parse_expr();
            if (posi < n && s[posi] == ')') posi++;
            cur = new_repeat(inside, k);
        } else {
            // skip unexpected characters safely
            posi++;
            continue;
        }

        if (first == -1) {
            first = cur;
        } else {
            // concatenate by creating a synthetic subtree:
            // store concatenation as repeat not possible, so flatten using sequence node idea
            // Instead, create a special chain via child/next is unavailable.
            // Simpler approach: represent concatenation as repeat of a grouped list is not enough.
            // So we encode concatenations immediately into an array-based sequence node.
            // To keep structure simple, we rebuild using special nodes below.
            // This branch should never be used with current node design, so replaced later.
        }
    }

    if (first == -1) {
        // empty expression, create harmless zero-repeat of 'A'
        int a = new_literal('A');
        return new_repeat(a, 0);
    }
    return first;
}

