typedef struct {
    int type;          // 0 literal, 1 repeat, 2 concat
    char ch;
    int left, right;   // concat
    int child;         // repeat
    ull mul;
    ull len;
} TNode;

static TNode *tn = NULL;
static int tsz = 0, tcap = 0;

static void ensure_tn() {
    if (tsz >= tcap) {
        tcap = tcap ? tcap * 2 : 1024;
        tn = (TNode *)realloc(tn, tcap * sizeof(TNode));
    }
}

static int t_lit(char c) {
    ensure_tn();
    tn[tsz].type = 0;
    tn[tsz].ch = c;
    tn[tsz].left = tn[tsz].right = tn[tsz].child = -1;
    tn[tsz].mul = 1;
    tn[tsz].len = 1;
    return tsz++;
}

static int t_rep(int child, ull mul) {
    ensure_tn();
    tn[tsz].type = 1;
    tn[tsz].child = child;
    tn[tsz].left = tn[tsz].right = -1;
    tn[tsz].mul = mul;
    tn[tsz].len = clamp_mul(tn[child].len, mul);
    return tsz++;
}

static int t_cat(int a, int b) {
    ensure_tn();
    tn[tsz].type = 2;
    tn[tsz].left = a;
    tn[tsz].right = b;
    tn[tsz].child = -1;
    tn[tsz].mul = 1;
    ull x = tn[a].len + tn[b].len;
    tn[tsz].len = x > INF ? INF : x;
    return tsz++;
}

static int parseE() {
    int res = -1;
    while (posi < n && s[posi] != ')') {
        int cur;
        if (isupper((unsigned char)s[posi])) {
            cur = t_lit(s[posi]);
            posi++;
        } else if (isdigit((unsigned char)s[posi])) {
            ull k = read_number();
            if (posi < n && s[posi] == '(') posi++;
            int inside = parseE();
            if (posi < n && s[posi] == ')') posi++;
            cur = t_rep(inside, k);
        } else {
            posi++;
            continue;
        }

        if (res == -1) res = cur;
        else res = t_cat(res, cur);
    }
    if (res == -1) {
        int a = t_lit('A');
        return t_rep(a, 0);
    }
    return res;
}

static char kth_char(int root, ull k) { // 1-indexed
    while (1) {
        if (tn[root].type == 0) return tn[root].ch;
        if (tn[root].type == 1) {
            ull childLen = tn[tn[root].child].len;
            if (childLen == 0) return '?';
            k = (k - 1) % childLen + 1;
            root = tn[root].child;
        } else {
            ull leftLen = tn[tn[root].left].len;
            if (k <= leftLen) root = tn[root].left;
            else {
                k -= leftLen;
                root = tn[root].right;
            }
        }
    }
}

