def uncompress_and_get_char(compressed: str, index: int) -> str:
    # We'll use a stack to process the compressed string
    # Each element is either a single character or a tuple (count, string)
    stack = []
    i = 0
    n = len(compressed)

    while i < n:
        ch = compressed[i]
        if ch.isalpha():
            stack.append(ch)
            i += 1
        elif ch.isdigit():
            # parse the number
            num_start = i
            while i < n and compressed[i].isdigit():
                i += 1
            count = int(compressed[num_start:i])
            # next char must be '('
            if i < n and compressed[i] == '(':
                i += 1  # skip '('
                # collect the sequence inside parentheses
                # we need to handle nested parentheses
                depth = 1
                seq_start = i
                while i < n and depth > 0:
                    if compressed[i] == '(':
                        depth += 1
                    elif compressed[i] == ')':
                        depth -= 1
                    i += 1
                seq = compressed[seq_start:i-1]  # exclude ')'
                # Push the repeated sequence as a compact representation
                stack.append((count, seq))
            else:
                # Should not happen per problem statement, but handle gracefully
                i += 1
        else:
            i += 1

    # Now we need to find the character at the given index
    # We'll traverse in reverse to find the right segment
    # First, compute total length of the uncompressed string
    # We'll do this by traversing the stack and expanding only as needed

    def get_length(item):
        if isinstance(item, str):
            return 1
        else:
            count, seq = item
            # recursively compute length of seq
            return count * compute_uncompressed_length(seq)

    def compute_uncompressed_length(s):
        # Simple recursive length computation
        total = 0
        j = 0
        while j < len(s):
            if s[j].isalpha():
                total += 1
                j += 1
            elif s[j].isdigit():
                num_start = j
                while j < len(s) and s[j].isdigit():
                    j += 1
                count = int(s[num_start:j])
                # skip '('
                j += 1  # '('
                depth = 1
                seq_start = j
                while j < len(s) and depth > 0:
                    if s[j] == '(':
                        depth += 1
                    elif s[j] == ')':
                        depth -= 1
                    j += 1
                # seq is s[seq_start:j-1]
                total += count * compute_uncompressed_length(s[seq_start:j-1])
            else:
                j += 1
        return total

    # Now find the character at index (1-based)
    # We'll process the stack from left to right, subtracting lengths

    for item in stack:
        if isinstance(item, str):
            if index == 1:
                return item
            index -= 1
        else:
            count, seq = item
            seq_len = compute_uncompressed_length(seq)
            total_len = count * seq_len
            if index <= total_len:
                # The character is inside this repeated sequence
                # Find which repetition and the offset
                # offset is 0-based within the repeated block
                offset = index - 1
                rep_index = offset // seq_len
                inner_offset = offset % seq_len
                # Recursively find the character in seq at position inner_offset+1
                return uncompress_and_get_char(seq, inner_offset + 1)
            else:
                index -= total_len

    # Should never reach here if index is valid
    return ''

