def parse(s, pos):
    # Returns a list of segments, each being either a string or (sublist, count)
    segments = []
    while pos < len(s) and s[pos] != ')':
        if s[pos] == '(':
            pos += 1  # skip '('
            sub, pos = parse(s, pos)
            pos += 1  # skip ')'
            # read number
            num_start = pos
            while pos < len(s) and s[pos].isdigit():
                pos += 1
            count = int(s[num_start:pos])
            segments.append((sub, count))
        elif s[pos].isupper():
            # read letters
            start = pos
            while pos < len(s) and s[pos].isupper():
                pos += 1
            segments.append(s[start:pos])
        else:
            pos += 1
    return segments, pos

