def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # The statement excerpt does not include the exact input format.
    # We support the standard compressed-string + queries style:
    # 1) Either: S Q i1 i2 ... iQ
    # 2) Or:     S i
    #
    # Compression rule assumed:
    # - Uppercase letters are literal characters.
    # - A number after a character or a parenthesized block means repetition.
    # - Parentheses may be nested.
    #
    # We answer each query by finding the i-th character in the fully expanded string
    # without actually expanding it.

    tokens = data
    s = tokens[0]

    # Parse remaining tokens as queries if present
    queries = []
    if len(tokens) >= 2:
        rem = tokens[1:]
        if len(rem) >= 1:
            # If first remaining token equals count of following queries, use it.
            try:
                q = int(rem[0])
                if q == len(rem) - 1:
                    queries = list(map(int, rem[1:]))
                else:
                    queries = list(map(int, rem))
            except:
                queries = []

    if not queries:
        # If no query given, nothing to output.
        return

    n = len(s)
    INF = 10**30

    # Recursive descent parser producing an AST-like structure:
    # node types:
    # ('lit', ch, length)
    # ('seq', [children], length)
    # ('rep', child, times, length)

    idx = 0

    def parse_number():
        nonlocal idx
        if idx >= n or not s[idx].isdigit():
            return 1
        val = 0
        while idx < n and s[idx].isdigit():
            val = val * 10 + ord(s[idx]) - 48
            if val > INF:
                val = INF
            idx += 1
        return val

    def capped_mul(a, b):
        if a == 0 or b == 0:
            return 0
        if a > INF // b:
            return INF
        return a * b

    def capped_add(a, b):
        c = a + b
        return c if c < INF else INF

    def parse_seq():
        nonlocal idx
        children = []
        total = 0
        while idx < n and s[idx] != ')':
            if s[idx] == '(':
                idx += 1
                child = parse_seq()
                if idx < n and s[idx] == ')':
                    idx += 1
                times = parse_number()
                length = capped_mul(child[2], times)
                node = ('rep', child, times, length) if times != 1 else child
            else:
                ch = s[idx]
                idx += 1
                node = ('lit', ch, 1)
                times = parse_number()
                if times != 1:
                    node = ('rep', node, times, capped_mul(1, times))
            children.append(node)
            total = capped_add(total, node[2 if node[0] != 'rep' else 3])
        if len(children) == 1:
            child = children[0]
            if child[0] == 'rep':
                return ('seq', children, total)
            return child if total == 1 or child[0] != 'seq' else child
        return ('seq', children, total)

    root = parse_seq()

    def node_len(node):
        t = node[0]
        if t == 'lit':
            return 1
        if t == 'seq':
            return node[2]
        return node[3]

    def kth(node, k):  # 1-indexed
        t = node[0]
        if t == 'lit':
            return node[1]
        if t == 'seq':
            for child in node[1]:
                ln = node_len(child)
                if k <= ln:
                    return kth(child, k)
                k -= ln
            return '?'
        # rep
        child, times, length = node[1], node[2], node[3]
        clen = node_len(child)
        if clen == 0:
            return '?'
        k = (k - 1) % clen + 1
        return kth(child, k)

    out = []
    total_len = node_len(root)
    for q in queries:
        if 1 <= q <= total_len:
            out.append(kth(root, q))
        else:
            out.append('?')

    sys.stdout.write("\n".join(out))

